package com.example.lifecycle;

import jakarta.annotation.PostConstruct;
import jakarta.annotation.PreDestroy;
import org.springframework.beans.BeansException;
import org.springframework.beans.factory.BeanNameAware;
import org.springframework.beans.factory.DisposableBean;
import org.springframework.beans.factory.InitializingBean;
import org.springframework.context.ApplicationContext;
import org.springframework.context.ApplicationContextAware;
import org.springframework.stereotype.Component;

@Component
public class EnterpriseResourceBean implements BeanNameAware, ApplicationContextAware, InitializingBean, DisposableBean {

    private String beanName;
    private ApplicationContext applicationContext;

    public EnterpriseResourceBean() {
        System.out.println("1. Instantiation: Constructor invoked.");
    }

    @Override
    public void setBeanName(String name) {
        this.beanName = name;
        System.out.println("2. BeanNameAware: Bean name is set to -> " + name);
    }

    @Override
    public void setApplicationContext(ApplicationContext applicationContext) throws BeansException {
        this.applicationContext = applicationContext;
        System.out.println("3. ApplicationContextAware: Context reference injected.");
    }

    @PostConstruct
    public void customPostConstruct() {
        System.out.println("4. @PostConstruct: Custom initialization annotation executed.");
    }

    @Override
    public void afterPropertiesSet() throws Exception {
        System.out.println("5. InitializingBean: afterPropertiesSet() called.");
    }

    public void customInitMethod() {
        System.out.println("6. Custom Init Method: XML or @Bean(initMethod) triggered.");
    }

    @Override
    public void destroy() throws Exception {
        System.out.println("8. DisposableBean: destroy() called during container shutdown.");
    }

    @PreDestroy
    public void customPreDestroy() {
        System.out.println("7. @PreDestroy: Teardown annotation executed.");
    }
}
